import pathlib,json
p=pathlib.Path(__file__).resolve().parent;sdk=json.loads((p/'c-sdk-analysis.json').read_text())
def quote(value):return '\n````json\n'+json.dumps(value,indent=2,ensure_ascii=True)+'\n````\n'
lines=['### New public SDK refusal: the requested no-new-refusal outcome is not met','', '**Neither exact form of (c) meets all requested gates.** Keeping LineMapSource internal breaks declaration bundling. Making it public repairs the missing type but introduces a new Adamic refusal for an ordinary public SourceFile caller. This is outside the 34 internal compiler views, so it must not be hidden by their clearance count.','', 'The emitted-public-API probe is:', '', '```ts','import * as ts from "./typescript.js";','export function probe(file: ts.SourceFile): ts.LineAndCharacter {','    return ts.getLineAndCharacterOfPosition(file, 0);','}','```','', '| Emitted SDK | Production checker errors | Cohere findings | Guarded optional-widening refusals |','| --- | ---: | ---: | ---: |']
for label,r in sdk['variants'].items():lines.append('| '+label+' | '+str(len(r['checker']['diagnostics']))+' | '+str(len(r['cohere_findings']))+' | '+str(sum(f['kind']=='Refused' and 'optional property lineMap' in f['reason'] for f in r['guarded_findings']))+' |')
lines+=['', 'Both cohere and the same guarded full-mode lowering binary report the new refusal, including when only the exported slot is made readonly:', '', '```text','optional property lineMap in LineMapSource absent from structural source SourceFile, which can hide fields','```','', 'Public SourceFile has no lineMap because its original member remains @internal. Newly public LineMapSource declares an optional lineMap, so this public view reintroduces the structural hiding rule. Its readonly variant is still refused because optional widening is independent of writable-slot invariance. The production checker accepts all four SDK probes; this is an Adamic relation refusal, not a TypeScript checker error.','', 'The readonly SDK control changes only the emitted interface member for this probe. It is not a full implementation or measurement of (d), and no narrow writer is claimed. The conditional compiler-side writable-slot refusal that requested (d) was not observed. Even a separate narrow writer would not change this SDK argument relation while its first parameter retains that public optional member. A further public API/cache-annotation change would be required; it is not silently folded into the requested experiment.','', 'Every SDK finding, including the baseline external function-without-a-body NotYet, is retained below. The SDK census is isolated to the consumer and emitted declaration bundle, uses LATENT_FULL=1 and LATENT_ASSERT_NO_OUTPUT=1, and has no backend output. It is additional evidence, not a substitute for the real ten-file runs.']
for label,r in sdk['variants'].items():lines+=['','**'+label+'**',quote({'production_checker':r['checker'],'cohere_findings':r['cohere_findings'],'guarded_findings':r['guarded_findings']})]
text='\n'.join(lines)+'\n';assert '\u2013' not in text and '\u2014' not in text
(p/'REPORT-C-SDK.md').write_text(text)
print('SDK report generated')
